<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>U.S. Department of State - Budget Overview and Contact</title>

    <!-- Meta tags for SEO and Social Media -->
    <meta property="og:title" content="U.S. Department of State - Budget Overview">
    <meta property="og:type" content="website">

    <!-- Styles for Accessibility (Skip Link Visibility) -->
    <style>
        body { 
            font-family: sans-serif; 
            line-height: 1.6; 
            margin: 0; 
            padding: 20px; 
            color: #333;
        }

        /* Skip to main content link */
        .skip-link { 
            position: absolute; 
            top: -40px; 
            left: 0; 
            background: #000; 
            color: #fff; 
            padding: 8px; 
            z-index: 100; 
            transition: top 0.3s;
        }

        .skip-link:focus { 
            top: 0; 
        }

        /* Headings */
        h1, h2, h3 { 
            color: #333; 
            margin-top: 1.5em; 
        }

        /* Tables */
        table { 
            width: 100%; 
            border-collapse: collapse; 
            margin: 20px 0; 
            font-size: 0.9em;
        }

        th, td { 
            border: 1px solid #ddd; 
            padding: 8px; 
            text-align: left; 
        }

        th { 
            background-color: #f4f4f4; 
        }

        caption { 
            font-weight: bold; 
            margin-bottom: 10px; 
        }

        /* Forms */
        fieldset { 
            border: 2px solid #ccc; 
            padding: 15px; 
            margin: 20px 0; 
            border-radius: 4px; 
        }

        legend { 
            font-weight: bold; 
            display: block; 
            margin-bottom: 10px; 
        }

        label { 
            display: block; 
            margin-top: 10px; 
            font-weight: bold; 
        }

        input[type="text"], 
        input[type="email"], 
        select, 
        textarea { 
            width: 100%; 
            padding: 8px; 
            box-sizing: border-box; 
            margin-top: 5px;
        }
    </style>
</head>
<body class="js">

    <!-- Skip to main content link for keyboard users -->
    <a href="#main-content" class="skip-link">Skip to main content</a>

    <!-- Header Landmark (Banner) -->
    <header role="banner">
        <div class="site-header">
            <!-- H1 is the only top-level heading on the page -->
            <h1><a href="/">U.S. Department of State</a></h1>

            <!-- Primary Navigation -->
            <nav aria-label="Main Navigation">
                <ul>
                    <li><a href="/about">About Us</a></li>
                    <li><a href="/news">News & Events</a></li>
                    <li><a href="/travel">Travel Information</a></li>
                    <li><a href="/careers">Careers</a></li>
                </ul>
            </nav>
        </div>
    </header>

    <!-- Secondary Navigation (if applicable) -->
    <nav aria-label="Secondary Navigation" class="secondary-nav">
        <ul>
            <li><a href="/contact-us">Contact Us</a></li>
            <li><a href="/accessibility">Accessibility</a></li>
        </ul>
    </nav>

    <!-- Main Landmark (Main Content) -->
    <!-- Fixes the 'landmark-one-main' violation by providing a clear main region -->
    <main id="main-content" role="main">

        <!-- Section 1: Introduction with Proper Heading Hierarchy -->
        <section aria-labelledby="intro-heading">
            <h2 id="intro-heading">Fiscal Year 2024 Budget Overview</h2>
            <p>The U.S. Department of State manages a complex budget to support diplomatic missions, security initiatives, and public diplomacy efforts worldwide.</p>
        </section>

        <!-- Section 2: Data Table (WCAG 1.3.1 Compliance) -->
        <!-- Note: Using native table elements instead of divs with role="grid" for better accessibility -->
        <section aria-labelledby="table-heading">
            <h2 id="table-heading">Departmental Expenditure by Region</h2>

            <!-- Caption provides a short summary of the table content -->
            <caption>The table below details the allocated budget (in millions USD) for key diplomatic regions in FY 2024.</caption>

            <table aria-describedby="table-heading">
                <thead>
                    <tr>
                        <!-- scope="col" indicates these headers apply to columns -->
                        <th scope="col">Region</th>
                        <th scope="col">Diplomatic Missions</th>
                        <th scope="col">Security Programs</th>
                        <th scope="col">Total Allocation ($M)</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <!-- scope="row" indicates these cells belong to a specific row -->
                        <td scope="row">North America</td>
                        <td>$450.2 M</td>
                        <td>$120.5 M</td>
                        <td>$570.7 M</td>
                    </tr>
                    <tr>
                        <td scope="row">Europe & Eurasia</td>
                        <td>$380.1 M</td>
                        <td>$210.3 M</td>
                        <td>$590.4 M</td>
                    </tr>
                    <tr>
                        <td scope="row">Latin America & Caribbean</td>
                        <td>$150.8 M</td>
                        <td>$85.2 M</td>
                        <td>$236.0 M</td>
                    </tr>
                </tbody>
            </table>
        </section>

        <!-- Section 3: Form with Fieldsets and Labels (WCAG 1.3.1 Compliance) -->
        <section aria-labelledby="contact-heading">
            <h2 id="contact-heading">Public Inquiry Form</h2>
            <p>Please fill out the form below to submit a general inquiry regarding our services.</p>

            <!-- Fieldset groups related inputs together, providing context via legend -->
            <fieldset>
                <legend>Contact Information</legend>

                <!-- Label explicitly linked to input via 'for' attribute matching input's 'id' -->
                <label for="full-name">Full Name</label>
                <input type="text" id="full-name" name="fullname" required autocomplete="name" aria-required="true">

                <label for="email-address">Email Address</label>
                <input type="email" id="email-address" name="email" required autocomplete="email" aria-describedby="email-hint">
                <span id="email-hint" class="visually-hidden">We will only use your email to respond to your inquiry.</span>

                <!-- Related fieldset for additional info -->
                <fieldset>
                    <legend>Inquiry Details</legend>

                    <label for="subject">Subject</label>
                    <select id="subject" name="subject" required autocomplete="off">
                        <option value="" disabled selected>Select a topic</option>
                        <option value="diplomacy">Diplomacy</option>
                        <option value="travel">Travel Advisories</option>
                        <option value="employment">Employment Opportunities</option>
                    </select>

                    <label for="message">Message</label>
                    <textarea id="message" name="message" rows="5" required></textarea>
                </fieldset>
            </fieldset>

            <button type="submit">Submit Inquiry</button>
        </section>

    </main>

    <!-- Aside Landmark (Complementary) -->
    <aside role="complementary" aria-label="Sidebar">
        <nav aria-label="Quick Links">
            <h3>Quick Links</h3>
            <ul>
                <li><a href="/faq">Frequently Asked Questions</a></li>
                <li><a href="/forms">Download Forms</a></li>
                <li><a href="/statistics">Statistical Data</a></li>
            </ul>
        </nav>
    </aside>

    <!-- Footer Landmark (Contentinfo) -->
    <footer role="contentinfo">
        <p>&copy; 2023 U.S. Department of State. All rights reserved.</p>

        <nav aria-label="Footer Navigation">
            <ul>
                <li><a href="/privacy-policy">Privacy Policy</a></li>
                <li><a href="#main-content">Skip to Main Content</a></li>
                <li><a href="/accessibility-statement">Accessibility Statement</a></li>
            </ul>
        </nav>
    </footer>

</body>
</html>
