    <!-- Styles for visual presentation and accessibility -->
    <style>
        body { 
            font-family: sans-serif; 
            line-height: 1.6; 
            margin: 0; 
            padding: 0; 
            color: #333;
        }
        .container { 
            max-width: 960px; 
            margin: 0 auto; 
            padding: 20px; 
        }
        /* Ensure headings are distinct */
        h1, h2, h3 { 
            color: #2c3e50; 
            margin-top: 1.5em; 
            margin-bottom: 0.5em;
        }
        a { 
            color: #0056b3; 
            text-decoration: none; 
        }
        a:hover { 
            text-decoration: underline; 
        }
        /* Form styling */
        input, select, textarea { 
            padding: 8px; 
            margin-bottom: 10px; 
            border: 1px solid #ccc; 
            font-family: inherit;
        }
        button {
            background-color: #0056b3;
            color: white;
            border: none;
            padding: 10px 20px;
            cursor: pointer;
