                    <li><a href="/">Home</a></li>
                    <li><a href="/news">News</a></li>
                    <li><a href="/opinion">Opinion</a></li>
                    <li><a href="/culture">Culture</a></li>
                </ul>
            </nav>
        </div>
    </header>

    <!-- Main Landmark: Identifies the primary content of the page -->
    <main id="main-content" role="main">

        <!-- Article Section -->
        <article>
            <h2>Breaking News: Regional Summit Concludes</h2>
            <p class="lead">Leaders from across the region gathered today to discuss economic cooperation and security protocols.</p>

            <figure>
                <img src="summit.jpg" alt="Photo of leaders shaking hands at the regional summit venue." width="600" height="400">
                <figcaption>The delegates are discussing key points in the conference hall.</figcaption>
