                </fieldset>

                <fieldset>
                    <legend>Email Address</legend>
                    <label for="email-input">Email:</label>
                    <input type="email" id="email-input" name="email" required aria-describedby="email-hint">
                    <span id="email-hint" class="visually-hidden">We will only use your email to send you our newsletter.</span>
                </fieldset>

                <fieldset>
                    <legend>Message</legend>
                    <label for="message-input">Your Message:</label>
                    <textarea id="message-input" name="message" rows="5" aria-required="true"></textarea>
                </fieldset>

                <button type="submit">Send Message</button>
            </form>

            <nav aria-label="Footer Navigation">
                <ul>
                    <li><a href="/privacy">Privacy Policy</a></li>
                    <li><a href="/terms">Terms of Service</a></li>
                    <li><a href="/advertising">Advertising</a></li>
                </ul>
            </nav>
        </div>
    </footer>

</body>
